const q = (id, question, choices, answer, rationale, lesson, extra = {}) => ({
  id: `enteral-nutrition-${id}`,
  question,
  choices,
  answer,
  rationale,
  reviewHref: `#${lesson}`,
  ...extra,
});

const core = [
  q("001", "Which principle most strongly favors enteral over parenteral nutrition?", ["A usable gastrointestinal tract that cannot be supported adequately by oral intake", "A need to bypass all intestinal function", "Complete mechanical obstruction", "Active bowel ischemia"], 0, "A usable gut with inadequate oral intake supports enteral nutrition; obstruction and active ischemia do not. This principle does not prove better clinical outcomes in every setting. The 2022 ASPEN guideline accepts either enteral or parenteral nutrition with similar energy delivery during the first ICU week in adults who are candidates for enteral feeding.", "enteral-decision"),
  q("002", "Which condition is the clearest reason to withhold enteral feeding?", ["Suspected bowel ischemia", "Stable low-dose vasopressor support after adequate resuscitation", "High nutrition risk with stable perfusion and a usable gut", "Dysphagia with a usable gut and inadequate oral intake"], 0, "Withhold feeding and urgently assess suspected bowel ischemia. The other settings can support carefully monitored enteral nutrition when clinically appropriate; vasopressor use alone is not an absolute exclusion.", "enteral-decision"),
  q("003", "Under the 2016 SCCM/ASPEN guideline, when should enteral nutrition be considered for a resuscitated, stable critically ill adult with high nutrition risk, a usable gut, and inadequate oral intake?", ["Within 24 to 48 hours", "After a mandatory seven-day delay regardless of nutrition risk", "Only after a mandatory fourteen-day trial without nutrition support", "Only after parenteral nutrition has failed"], 0, "The guideline supports early initiation within 24 to 48 hours once adequately resuscitated and stable. Its first-week exception concerns patients with low nutrition risk, normal baseline nutrition status, and low disease severity; it does not justify a fixed delay in this high-risk case.", "enteral-decision"),
  q("004", "A patient has escalating vasopressor doses, cool extremities, and rising lactate. What is the best nutrition response?", ["Withhold enteral feeding and urgently reassess perfusion", "Keep the current feeding rate but stop further advancement", "Switch to postpyloric feeding without reassessing perfusion", "Use a slower gastric infusion while vasopressor needs continue to escalate"], 0, "Escalating vasopressor needs with impaired-perfusion findings require withholding feeding and urgent reassessment. Continuing the previous rate or changing the tube destination does not resolve instability. Lactate alone does not establish enteral intolerance or diagnose bowel ischemia.", "enteral-decision"),
  q("005", "Which finding supports cautious low-dose feeding after shock?", ["Resuscitation is complete and perfusion is stable", "Vasopressor requirements are still escalating despite resuscitation", "Abdominal distention is increasing while perfusion deteriorates", "A fixed number of hours has elapsed despite persistent instability"], 0, "Resuscitation with stable perfusion can permit carefully monitored low-dose feeding, including selected patients on stable low-dose vasopressor support. Elapsed time alone does not establish safety, and escalating support or concerning abdominal findings requires reassessment.", "enteral-decision"),
  q("006", "Why should safe oral intake be reassessed before placing a feeding tube?", ["Enteral tube feeding should not replace an oral diet that safely meets needs", "Tube placement is indicated whenever an oral nutrition supplement is used", "Tube feeding prevents aspiration regardless of swallowing function", "Tube placement resolves drug-nutrient interactions without medication review"], 0, "Tube feeding supports patients who cannot meet their needs by voluntary oral intake. If safe oral intake already meets those needs, a feeding tube is not indicated solely to deliver nutrition. A tube does not eliminate aspiration risk or medication interactions.", "enteral-decision"),
  q("007", "Which outcome is a recognized advantage of enteral nutrition?", ["Preservation of gastrointestinal structure and function", "Avoidance of intestinal absorption because nutrients enter the bloodstream directly", "Prevention of aspiration because the feeding tube replaces airway protection", "Provision of the full water requirement whenever the calorie target is met"], 0, "Enteral nutrition uses the gut and helps prevent intestinal atrophy. Parenteral nutrition bypasses the gut. Enteral feeding still carries aspiration risk, and meeting calorie needs does not establish adequate water delivery.", "enteral-decision"),
  q("008", "What is the most defensible reason to initiate enteral nutrition in a malnourished patient?", ["Oral intake is inadequate and the gastrointestinal tract is functional", "Adequate safe oral intake is present, but a tube formula is more convenient", "A central venous line is available, even though safe oral intake meets needs", "One low albumin result is present, even though safe oral intake meets needs"], 0, "Enteral support is favored when voluntary oral intake cannot meet nutritional needs and the gut is usable. Formula convenience, an existing intravenous line, or an isolated laboratory result does not override the stated ability to meet needs safely by mouth.", "enteral-decision"),

  q("009", "For a patient with adequate gastric function and low aspiration risk, which feeding destination offers the most flexibility for bolus, intermittent, or continuous schedules?", ["Gastric access", "Jejunal access regardless of tolerance", "Postpyloric access solely to increase the size of boluses", "Either gastric or jejunal access with identical schedule options"], 0, "Gastric access supports multiple schedules when gastric function, tolerance, and aspiration risk permit. Jejunal schedules are more limited and generally use controlled delivery. Do not select a postpyloric destination simply to permit larger boluses; tip location affects the feeding plan.", "access-route"),
  q("010", "Which adequately resuscitated, stable adult with a usable small intestine most strongly warrants reassessment for postpyloric feeding?", ["Persistent aspiration risk with severe gastroparesis despite preventive measures", "Normal gastric emptying, good gastric tolerance, and low aspiration risk", "Good gastric tolerance but a longer anticipated duration of feeding", "Adequate gastric feeding with a preference for a simpler home schedule"], 0, "Severe gastroparesis with persistent aspiration risk supports assessment for small bowel access. Normal emptying and tolerance do not establish that need; longer duration concerns access longevity, and home convenience alone does not justify bypassing a usable stomach. Postpyloric feeding does not eliminate aspiration.", "access-route"),
  q("011", "Why does the 2024 AuSPEN pediatric consensus recommend continuous pump delivery for children receiving jejunal feeds?", ["The jejunum has limited reservoir capacity compared with the stomach", "Jejunal access prevents absorption of all enteral nutrients", "A jejunal tip provides the same bolus-volume flexibility as a gastric tip", "A pump eliminates the need to monitor jejunal feeding tolerance"], 0, "The pediatric consensus recommends continuous pump delivery because the jejunum has limited reservoir capacity; boluses may cause intolerance and dumping physiology. Jejunal feeding can provide nutrition, but gastric and jejunal schedules are not interchangeable, and tolerance still requires monitoring. This pediatric recommendation does not establish a mandatory 24-hour adult schedule.", "access-route"),
  q("012", "Under the 2017 ASPEN recommendations, which method confirms an adult's blindly placed short-term feeding tube before its initial use?", ["Radiographic confirmation", "Air auscultation alone after inserting the tube", "Aspirate pH testing alone without radiographic confirmation", "Absence of coughing or respiratory distress during insertion"], 0, "Obtain and properly interpret a radiograph showing the entire tube course and tip before initial feeding, fluid, or medication administration in this adult case. Auscultation is unreliable, pH alone does not replace the recommended initial radiograph, and misplacement may occur without respiratory symptoms. Pediatric and neonatal verification requires its own risk-based protocol.", "access-route"),
  q("013", "Which finding most strongly requires reassessment for possible feeding-tube migration before continued use?", ["A change in external tube length with new coughing", "An ENFit syringe still connects to the tube", "A previous placement image is available and no subsequent clinical change is reported", "The documented external marking is unchanged and no new symptoms are reported"], 0, "Changed external length with new coughing raises concern for displacement: hold feeding, fluids, and medication through the tube until the intended location is confirmed. These findings do not diagnose the new tip location. A connector that fits and a previous image cannot resolve new migration concerns; unchanged markings and no new symptoms do not prove ongoing placement either.", "access-route"),
  q("014", "What safety problem is ENFit designed to reduce?", ["Wrong-route connection between enteral and nonenteral systems", "Use of a medication formulation that is unsuitable for the tube", "Use of a feeding tube whose tip has migrated", "Contamination of formula during preparation or administration"], 0, "ENFit connector geometry is designed to reduce cross-system misconnections. It does not establish medication suitability, tube-tip position, or formula sterility. Trace the line and verify the connection before use, use compatible enteral equipment, and do not rely on color or labeling alone.", "access-route"),
  q("015", "Which route is most appropriate when long-term gastric feeding is expected and gastric function is stable?", ["A gastrostomy after individualized procedural assessment", "A jejunostomy solely because a longer course automatically requires a jejunal destination", "Central parenteral nutrition solely because the expected feeding duration is long", "A short-term nasal route without reconsidering access as long-term support is planned"], 0, "A gastrostomy provides access through the skin to the stomach, whereas a jejunostomy ends in the small intestine. Nasogastric tubes are primarily short-term access. For the stated long-term gastric plan, consider gastrostomy after individualized assessment; duration alone does not establish a need to bypass a usable stomach.", "access-route"),
  q("016", "Which statement about tube selection is most accurate?", ["Expected duration, anatomy, aspiration risk, gastric function, and medication needs all matter", "Expected duration alone determines whether the tube must end in the jejunum", "Gastric and jejunal tube tips are interchangeable once the same formula is selected", "Choosing a suitable feeding formula removes the need to review medication compatibility"], 0, "Assess both the intended duration and the actual feeding destination. Nasogastric access is primarily short term; gastrostomy and jejunostomy reach different organs. Aspiration remains a risk, and medications require product-specific compatibility and absorption review.", "access-route"),

  q("017", "A stable adult with jejunal access develops intolerance during large, rapid feedings. Which delivery change is most appropriate to assess?", ["Continuous pump delivery at an individualized rate", "Keep the same rapid boluses because the prescribed daily volume is correct", "Use a shorter running time and increase the rate without assessing tolerance", "Select the rate from the bag volume alone without a daily schedule"], 0, "Assess controlled continuous delivery and set the rate and running hours according to the prescribed volume and tolerance. Jejunal schedules are more limited than gastric schedules. A correct daily target does not establish that rapid delivery is tolerated; shortening the schedule raises the required rate, and container volume alone does not define the plan.", "delivery-prescription"),
  q("018", "Which additional information is needed to calculate daily formula volume from an order that states only feed at 65 mL per hour?", ["The daily duration or volume target", "The formula calorie density without a feeding duration", "The water percentage on the formula label without a feeding duration", "The formula bag capacity without a scheduled volume or feeding duration"], 0, "Daily volume equals rate multiplied by the hours actually delivered. Formula energy density, water percentage, or bag capacity alone does not supply the missing daily duration or volume target.", "delivery-prescription"),
  q("019", "For a patient who tolerates the prescribed rate and daily volume, what is a practical advantage of a cyclic pump-feeding schedule?", ["It provides a feeding-free interval while maintaining controlled pump delivery", "Its off-feeding interval establishes that daytime oral intake is adequate", "Its shorter running time preserves the same daily volume without changing the rate", "Its use establishes that the tube destination no longer affects the schedule"], 0, "A cyclic schedule provides controlled infusion during a defined part of the day and time off feeding that may fit activity or home routines. Appetite and oral intake still need assessment. Fewer running hours at an unchanged rate reduce delivered volume, and the tube tip and tolerance remain relevant.", "delivery-prescription"),
  q("020", "An adult at high refeeding risk has severely low phosphate before enteral feeding is started. Which plan best follows the 2020 ASPEN consensus?", ["Correct the severe deficiency and delay starting or increasing calories until corrected", "Start the full energy target while waiting for the next scheduled phosphate result", "Advance to full energy as long as baseline potassium is normal", "Ignore the phosphate result because the calories will enter through the gut"], 0, "Severely low phosphate, potassium, or magnesium calls for delaying calorie initiation or increases until corrected under the 2020 ASPEN consensus. Enteral calories can trigger refeeding physiology, and a normal potassium result does not resolve a severe phosphate deficit. Use cautious advancement and close monitoring rather than starting at the full target.", "delivery-prescription"),
  q("021", "Why should actual delivered volume be audited?", ["Interruptions can make prescribed and received nutrition substantially different", "A correctly programmed hourly rate is sufficient to establish the daily intake", "The formula container label establishes intake even when part is not delivered", "Ordered calories can substitute for checking how much formula reached the patient"], 0, "Use the amount actually received, not just the order or nominal container amount. If feeding is interrupted or part of a serving is spilled, those portions are not delivered nutrition. The displayed rate must be interpreted with actual feeding time and volume.", "delivery-prescription"),
  q("022", "What is the purpose of a prescribed volume-based feeding protocol?", ["To target a safe daily volume despite predictable interruptions", "To replace a tolerance assessment whenever feeding has been interrupted", "To raise the rate until all missed feeding is replaced, without prescribed limits", "To count the ordered daily target as delivered intake even after a hold"], 0, "A daily volume target can guide adjustments within prescribed limits after interruptions. Reassess patient condition, tube destination, and tolerance before changing delivery. The protocol does not authorize unlimited catch-up, replace monitoring, or establish that ordered volume actually reached the patient.", "delivery-prescription"),
  q("023", "Which prescription is most complete?", ["Formula, access, method, rate or volume, schedule, flushes, advancement, and monitoring", "Formula, access, method, rate, schedule, and advancement, with supplemental water and monitoring left unspecified", "Formula, method, rate, flushes, and monitoring, with the feeding destination and schedule left unspecified", "Formula, access, daily volume, flushes, and monitoring, with delivery method and advancement left unspecified"], 0, "A prescription should describe what is given, where it is delivered, how much and when it runs, the water plan, and how delivery is assessed. The complete option makes these parts explicit. Naming a product or an hourly rate alone does not establish delivered nutrition or hydration.", "delivery-prescription"),
  q("024", "Which patient is the best candidate for gastric bolus feeding after individualized assessment?", ["A stable patient with a mature gastrostomy, good gastric tolerance, and low aspiration risk", "A stable patient with severe gastroparesis and recurrent aspiration during gastric feeds", "A stable patient with jejunal access who does not tolerate rapid feedings", "A patient with worsening shock and escalating vasopressor needs"], 0, "Stable gastric access, good tolerance, and low aspiration risk support consideration of bolus feeding. Severe gastroparesis or recurrent aspiration warrants reassessing destination and method; jejunal intolerance favors controlled delivery. Worsening shock requires perfusion assessment and withholding unsafe feeding rather than choosing boluses.", "delivery-prescription"),

  q("025", "A stable critically ill adult is starting enteral nutrition, with adequate digestion and absorption and no defined specialty-formula indication. Which formula is the recommended initial choice in the 2016 SCCM/ASPEN guideline?", ["A standard polymeric formula", "An elemental formula solely because its protein is more extensively broken down", "A disease-specific formula selected from the diagnosis alone", "A higher-cost formula selected without reviewing its composition"], 0, "The guideline recommends a standard polymeric formula initially for critically ill adults. Greater protein hydrolysis, a disease label, or a higher price does not establish a patient-specific advantage. Reassess composition and tolerance if a defined indication emerges.", "formula-selection"),
  q("026", "Which compositional feature defines a peptide-based enteral formula?", ["Hydrolyzed protein supplied as smaller peptides", "Intact protein as the defining protein form", "Free amino acids as the sole protein source in an amino-acid-based elemental formula", "An energy density of 2 kcal per mL regardless of protein form"], 0, "Peptide-based formulas supply hydrolyzed protein as smaller peptides. Standard polymeric formulas use intact protein, while amino-acid-based elemental formulas use free amino acids. Fat composition and energy density vary by product and do not define the peptide-based category.", "formula-selection"),
  q("027", "A patient is switched to an enteral formula labeled 2 kcal per mL. What is the best approach to reassessing hydration?", ["Use product free-water data and actual daily volume, then include other fluid sources and individual needs", "Use the entire formula volume as its free-water content", "Keep supplemental water unchanged without checking the new volume or other intake", "Use kcal per mL alone to determine whether the water target is met"], 0, "The energy-density label does not establish water delivery. Calculate formula water from product data and the volume actually received, then add flushes and other intake and compare with the individualized target. Formula volume is not all water, and a change in the prescription warrants reassessment.", "formula-selection"),
  q("028", "What is the strongest basis for selecting a disease-specific enteral formula?", ["A patient-specific assessment of composition, clinical evidence, tolerance, and cost", "The diagnosis alone, without checking the nutrient profile", "A higher price as evidence of better clinical outcomes", "The specialty label as a reason to continue despite poor tolerance"], 0, "The 2017 ASPEN safe-practice guidance calls for evaluating the nutrient profile, clinical efficacy, tolerance, evidence, and cost of specialty formulas. A diagnosis, price, or label alone does not demonstrate superiority or justify ignoring patient response. A defined indication may support a specialty choice.", "formula-selection"),
  q("029", "According to the 2016 SCCM/ASPEN guideline, when should both soluble and insoluble fiber be avoided in critically ill adults?", ["High risk of bowel ischemia or severe dysmotility", "Hemodynamic stability alone, without a bowel perfusion or motility concern", "A mature gastric tube alone, with preserved bowel function", "A need for volume restriction alone, with preserved bowel perfusion and motility"], 0, "The guideline advises avoiding both soluble and insoluble fiber in critically ill adults at high risk of bowel ischemia or with severe dysmotility. Stability, a mature gastric tube, and volume restriction alone do not establish that contraindication. This population-specific caution does not authorize feeding an ischemic bowel.", "formula-selection"),
  q("030", "What determines total daily water delivery?", ["Formula free water plus water delivered in flushes, medication fluids, oral intake, and intravenous sources", "The full formula volume plus its free-water volume as a second contribution", "Formula free water and scheduled flushes, excluding medication and intravenous fluids", "The prescribed daily water target regardless of what was actually delivered"], 0, "Add the water delivered from each source once, using formula water content rather than treating all formula volume as water. Medication fluids, including intravenous sources, contribute to the overall intake. Compare actual delivery with the individualized target; a written target is not evidence that the water was received.", "formula-selection"),
  q("031", "With unchanged renal concentrating capacity and insufficient water intake, why can a higher renal solute load increase dehydration risk?", ["It increases obligatory water needed for solute excretion", "It lowers the minimum urine volume needed for solute excretion", "It replaces urinary water losses with additional formula calories", "It prevents protein metabolism from producing urinary solute"], 0, "Urea from protein metabolism and electrolytes contribute to urinary solute. At the same renal concentrating capacity, clearing a higher solute load requires more urinary water, which can worsen a water deficit when intake is insufficient. The minimum required urine volume does not fall; formula calories do not replace water, and protein metabolism still produces urea. Higher solute intake alone does not prove dehydration when sufficient water is available. Assess the total water supply and renal status.", "formula-selection"),
  q("032", "After evaluation confirms fat malabsorption, which formula strategy is reasonable to assess alongside the cause and severity?", ["Consider a semi-elemental or peptide-based formula and review its fat composition", "Increase intact long-chain fat without checking absorption or tolerance", "Remove all protein solely because fat is poorly absorbed", "Choose a specialty formula from its label without examining composition"], 0, "The 2023 ASPEN fat-malabsorption practice tool describes changing to a semi-elemental formula as an option for selected patients. Review the product composition and patient response; this is not a universal requirement or proof of better outcomes. More intact long-chain fat without assessment, removing all protein, and relying on a label do not address the defined problem.", "formula-selection"),

  q("033", "Which dosage form should not be crushed for tube administration?", ["An extended-release tablet", "An immediate-release tablet whose product instructions permit crushing", "A powder prepared according to verified tube-administration instructions", "A liquid verified as compatible with the selected tube"], 0, "Do not crush an extended-release tablet: disrupting its release mechanism can deliver too much drug at once. The other options explicitly require verified product and tube compatibility.", "medication-administration"),
  q("034", "Two medications have been verified as compatible with the intended tube, with no prolonged feeding hold required. Which sequence is safest?", ["Pause feeding; flush, give the first drug, flush, give the second drug, flush, and restart promptly", "Combine the two drugs in one syringe because each is individually compatible", "Add the drugs directly to the formula rather than interrupting delivery", "Give the drugs separately but omit the intervening flush"], 0, "The 2017 ASPEN safe-practice guidance recommends pausing feeding, administering medications separately, and flushing before, between, and after doses. Separate compatibility does not establish compatibility when mixed. Restart promptly after administration unless a specific interaction or clinical condition requires longer separation.", "medication-administration"),
  q("035", "Why should medications not be added directly to enteral formula?", ["Drug stability, absorption, compatibility, and tube patency can be compromised", "Mixing is safe whenever the medication is sold as an oral liquid", "A freshly mixed formula bag guarantees drug stability for the entire feeding period", "A drug that can be taken with food is automatically compatible with a formula bag"], 0, "Do not add medications directly to enteral formula. Solid and liquid dosage forms can have physical, chemical, nutrient-interaction, and obstruction problems; an oral liquid or ordinary food instruction does not establish formula-bag compatibility.", "medication-administration"),
  q("036", "Which interaction can reduce ciprofloxacin absorption?", ["Complexation with formula calcium, magnesium, or iron", "Vitamin K in formula directly antagonizing the antibiotic's antibacterial action", "Minerals increasing bioavailability by keeping the antibiotic in the feeding solution", "Crushing an immediate-release tablet eliminating every drug-nutrient interaction"], 0, "Fluoroquinolones can chelate polyvalent cations, reducing bioavailability. Formula compatibility and cation-related absorption are separate checks: a suitable immediate-release preparation does not eliminate the interaction.", "medication-administration"),
  q("037", "Which monitoring strategy is most useful when enteral nutrition affects phenytoin exposure?", ["Use clinical assessment and drug concentrations with a drug-specific feeding plan", "Increase every dose before reviewing actual administration or feeding timing", "Use INR alone to judge phenytoin exposure", "Use the warfarin feeding schedule without checking phenytoin-specific instructions"], 0, "Enteral feeding can reduce phenytoin absorption. Review administration and feeding timing together with seizure control and serum phenytoin concentration. INR measures warfarin response, and a warfarin schedule does not establish phenytoin instructions.", "medication-administration"),
  q("038", "A medication order is transferred from gastric to jejunal delivery. Why must its formulation and administration method be reassessed?", ["Bypassing gastric conditions or a primary absorption site can change drug dissolution and exposure", "The same preparation and exposure can be assumed because both routes use a feeding tube", "A larger water flush establishes that gastric and jejunal delivery are equivalent", "An oral liquid designation alone establishes suitability for jejunal delivery"], 0, "The distal tip affects the conditions for dissolution and absorption. Evaluate the exact drug and formulation before applying a gastric method to jejunal delivery. More water or an oral liquid label does not establish site compatibility, and exposure should not be assumed unchanged.", "medication-administration"),
  q("039", "A tube-fed patient develops loose stools after several liquid medications are added. Which formulation characteristics warrant review?", ["Sorbitol content and high osmolality", "The oral liquid designation as proof that the preparation cannot contribute", "The absence of tablet crushing as proof of good gastrointestinal tolerance", "Individual tube compatibility as proof that excipients cannot cause symptoms"], 0, "Sorbitol is a cathartic, and high-osmolality liquid medications can cause gastrointestinal disturbances. An oral label, lack of crushing, or tube compatibility does not exclude adverse effects from the formulation. Assess other causes of diarrhea as well; timing alone does not prove a medication caused it.", "medication-administration"),
  q("040", "What is the safest rule for holding feeding around a medication?", ["Use drug-specific evidence and monitoring rather than a universal interval", "Copy the warfarin plan to every drug without checking product instructions", "Choose the longest hold possible regardless of the medication's interaction", "Apply a two-hour hold before and after every medication, including noninteracting drugs"], 0, "Check the exact product and the interaction. Warfarin and phenytoin have specific feeding-separation examples, and their intervals can overlap; that does not establish one plan for every medication.", "medication-administration"),
  q("041", "What device should be used to administer a medication through an ENFit tube?", ["A compatible enteral syringe", "An intravenous Luer-lock syringe attached using an improvised connector", "An oral syringe selected by color without verifying compatibility with the actual tube", "An unlabelled syringe that is assumed suitable because it appears to fit"], 0, "Use equipment intended for enteral administration and compatible with the actual tube. Oral/feeding-tube syringes should be clearly distinguished from intravenous syringes to prevent wrong-route administration. Color or apparent fit alone is not a compatibility check; do not improvise an intravenous connection.", "medication-administration"),
  q("042", "Which action best reduces warfarin variability during enteral therapy?", ["Keep vitamin K exposure and administration practice consistent while monitoring INR", "Remove all vitamin K from the patient's diet and stop checking INR", "Increase the dose solely because the formula carries a diabetes label", "Mix warfarin into the formula bag to avoid a feeding interruption"], 0, "Formula binding and changes in vitamin K intake can alter warfarin response. Reconcile product composition and medication timing, keep vitamin K exposure consistent, and monitor INR. The formula's disease label alone does not determine a dose.", "medication-administration"),

  q("043", "A critically ill adult receiving gastric enteral nutrition has no contraindication to head elevation. Which positioning measure belongs in the aspiration-prevention bundle?", ["Elevate the head of the bed 30 to 45 degrees when clinically feasible", "Keep the patient supine because the feeding tube tip was confirmed in the stomach", "Omit head elevation because endotracheal intubation prevents all aspiration", "Replace positioning and sedation review with routine residual checks alone"], 0, "The 2016 SCCM/ASPEN adult ICU guidance recommends head elevation of 30 to 45 degrees for intubated patients receiving enteral nutrition. Proper tube position, sedation review, and assessment of aspiration risk remain necessary. Intubation does not prevent small-volume aspiration, and residual checks do not replace the bundle.", "monitoring-complications"),
  q("044", "An adult ICU patient is stable without vasopressors and has a gastric residual of 350 mL without vomiting, pain, distention, or other intolerance signs. Under the 2016 SCCM/ASPEN guidance, how should this value be used?", ["Avoid an automatic feeding hold while reassessing tolerance and aspiration precautions", "Automatically hold feeding until the residual is zero despite the absence of other findings", "Use the value below 500 mL as proof that aspiration precautions are unnecessary", "Apply the same 500 mL rule to neonatal feeding without assessing the population"], 0, "The 2016 adult ICU guideline advises against automatically holding feeding for residuals below 500 mL without other intolerance signs. Values from 200 to 500 mL still raise concern and warrant measures to reduce aspiration risk. This is a population-specific recommendation, not proof of normal tolerance or a neonatal threshold; vasopressor guidance may use a different approach.", "monitoring-complications"),
  q("045", "An adult has an uncomplicated occlusion of a correctly positioned feeding tube. What is the initial approach after checking for kinks?", ["Follow the institutional procedure using warm water and gentle back-and-forth syringe movement", "Begin with an enzyme mixture before trying water", "Use an acidic carbonated beverage as the preferred first-line fluid", "Increase syringe pressure until the obstruction is forced through"], 0, "The 2017 ASPEN safe-practice guidance recommends warm water and gentle technique first. Acidic beverages can worsen formula precipitation; forceful pressure is not the recommended gentle approach. Enzyme products or approved devices are subsequent options when water fails, used by trained staff under the appropriate protocol.", "monitoring-complications"),
  q("046", "A stable critically ill adult receiving enteral nutrition develops diarrhea. What should be reviewed before attributing it to the formula alone?", ["Medications such as antibiotics or sorbitol preparations, and possible infectious causes", "The formula name as sufficient evidence of the cause", "A single liquid stool as proof that enteral feeding must be permanently stopped", "The absence of a formula change as a reason to exclude medication effects"], 0, "The 2016 SCCM/ASPEN guideline describes medications, infection, formula composition, delivery, and contamination as possible contributors. Review the patient, stool pattern, and fluid and electrolyte status. A product name or one stool does not establish the cause, and medication effects can arise without a formula change; do not automatically interrupt feeding solely for diarrhea in the stated ICU setting.", "monitoring-complications"),
  q("047", "During the first two days of enteral feeding in a malnourished adult, phosphate, potassium, and magnesium fall substantially from baseline. Which interpretation best fits this pattern?", ["Treat it as a refeeding warning and promptly evaluate the electrolyte changes and energy exposure", "Exclude refeeding because the baseline serum electrolytes were normal", "Exclude refeeding because nutrition was delivered enterally rather than intravenously", "Correct phosphate alone and disregard the concurrent potassium and magnesium changes"], 0, "Refeeding can cause substantial decreases in phosphate, potassium, and magnesium after calories are reintroduced. Normal initial serum concentrations do not exclude total-body depletion, and enteral nutrition is a possible trigger. Assess all three electrolytes, the clinical condition, other causes, and energy delivery rather than dismissing the pattern or addressing phosphate alone.", "monitoring-complications"),
  q("048", "How should formula osmolality be considered when evaluating diarrhea during enteral nutrition in a critically ill adult?", ["Assess it alongside medications, infection, delivery, and the clinical findings", "Treat the osmolality label alone as proof that formula caused the diarrhea", "Use an isotonic formula label to exclude infectious diarrhea", "Exclude medication effects whenever the formula is isotonic"], 0, "Formula osmolality is one possible contributor described in the 2016 SCCM/ASPEN guideline, not a diagnosis by itself. Neither isotonic nor higher-osmolality labeling excludes medications or infection. Use a clinical assessment rather than assigning every episode to one formula characteristic.", "monitoring-complications"),
  q("049", "Why should ordered and delivered volumes both be charted?", ["A patient can receive substantially less nutrition than prescribed", "The ordered daily volume can be charted as delivered whenever the pump rate is correct", "The full bag volume can be charted as intake even if the patient receives only part", "The order can replace the intake record once the correct formula has been selected"], 0, "Separate the intended daily volume from the volume actually received. Rate, container size, and formula selection do not prove delivery. Comparing the two records reveals a deficit that would be hidden if ordered volume were copied into the intake record.", "monitoring-complications"),
  q("050", "An adult receives commercial liquid formula through an open feeding system in the hospital. Which practice best reduces microbial contamination?", ["Use hand hygiene and aseptic handling, and follow manufacturer and facility preparation, storage, hang-time, and equipment-change instructions", "Add fresh formula to the existing container and restart the hang-time clock with each refill", "Extend the hang time whenever the formula still looks and smells unchanged", "Wash and reuse equipment labeled for single use to avoid replacing the feeding system"], 0, "Contamination prevention combines correct handling with product- and setting-specific time limits and equipment instructions. Topping off does not reset exposure time, normal appearance does not establish microbiological safety, and washing does not authorize reuse of equipment labeled for single use.", "monitoring-complications"),
];

const rateCases = [
  [1200, 20], [1440, 24], [1500, 18], [1680, 21], [1800, 20],
  [1000, 16], [1320, 22], [1560, 24], [1750, 20], [2000, 24],
].map(([volume, hours], index) => {
  const rate = Math.round(volume / hours * 10) / 10;
  const exact = Number.isInteger(volume / hours * 10);
  return q(`06${index}`, `A daily enteral volume target is ${volume} mL and feeding will run for ${hours} hours. What calculated pump rate corresponds to the target? Round to the nearest tenth of a mL per hour.`, [`${rate} mL/hour`, `${Math.round(rate * 2 * 10) / 10} mL/hour`, `${hours} mL/hour`, `${volume} mL/hour`], 0, `${volume} mL divided by ${hours} hours ${exact ? "equals" : "is approximately"} ${rate} mL per hour${exact ? "." : " when rounded to the nearest tenth. The rounded rate approximates the target volume."}`, "delivery-prescription");
});

const deliveredVolumeCases = [
  [45, 24], [55, 20], [65, 18], [70, 22], [80, 16],
  [85, 20], [90, 24], [95, 18], [100, 14], [110, 12],
].map(([rate, hours], index) => {
  const volume = rate * hours;
  return q(`07${index}`, `A feeding runs at ${rate} mL per hour for ${hours} hours. What volume is delivered?`, [`${volume} mL`, `${rate + hours} mL`, `${rate * 30} mL`, `${Math.round(volume / 2)} mL`], 0, `${rate} mL per hour multiplied by ${hours} hours equals ${volume} mL.`, "delivery-prescription");
});

const waterCases = [
  [1200, 0.80, 1500], [1500, 0.76, 1800], [1000, 0.85, 1600], [1800, 0.70, 2000], [1250, 0.82, 1700],
  [1400, 0.78, 1900], [1600, 0.74, 2100], [1100, 0.84, 1500], [1750, 0.72, 2200], [1300, 0.81, 1800],
].map(([volume, fraction, target], index) => {
  const formulaWater = Math.round(volume * fraction);
  const additional = target - formulaWater;
  return q(`08${index}`, `A patient receives ${volume} mL of formula that is ${Math.round(fraction * 100)} percent free water. The individualized water target is ${target} mL before other sources. How much additional water remains?`, [`${additional} mL`, `${formulaWater} mL`, `${target} mL`, `${volume} mL`], 0, `Formula provides ${formulaWater} mL. Subtracting this from ${target} mL leaves ${additional} mL before medication, oral, and intravenous water are counted.`, "formula-selection");
});

const diagnosticCases = [
  ["A newly placed small-bore nasal tube has not been confirmed and medication is due.", "Hold use and obtain evidence-based placement confirmation", "An incorrectly placed nasogastric tube can cause serious pulmonary complications when material is administered through it. Withhold use until the location is confirmed. Drug-form compatibility or a suitable syringe does not establish the tube tip location; this question does not specify a confirmation test.", "access-route", ["Give the medication before placement is checked because only nutrition needs to wait", "Treat the presence of a compatible enteral connector as proof of the tube position", "Choose a larger medication-water flush instead of verifying the tube position"]],
  ["An adult with a newly used jejunostomy develops cramping and diarrhea during four rapid 400 mL boluses. Placement has been confirmed, and the nutrition team is reviewing delivery tolerance.", "Reassess the regimen and use controlled pump delivery with an individualized rate and schedule", "The 2017 ASPEN safe-practice guidance recommends matching the schedule to patient condition, tolerance, goals, and tube destination. Jejunal feeding may be better tolerated as periodic continuous feeding; this symptomatic new regimen warrants controlled delivery and reassessment. The case does not establish a universal lifelong schedule or a rule prohibiting every adult jejunal bolus.", "delivery-prescription", ["Repeat the same rapid boluses without reviewing the rate or symptoms", "Use gastric bolus tolerance as proof that this jejunal regimen must be tolerated", "Commit to continuous feeding 24 hours daily indefinitely without reassessment"]],
  ["A patient on a dense formula becomes hypernatremic with rising BUN and low urine output.", "Recalculate all water sources, losses, kidney function, and flush delivery", "Inadequate fluid intake can cause hypernatremia, and dehydration may accompany rising BUN and reduced urine output. Kidney dysfunction can also raise BUN, so the findings do not prove that formula density is the sole cause. Promptly reassess hydration, all delivered fluids, losses, and renal status before choosing a patient-specific correction.", "formula-selection", ["Double the water flush volume immediately without assessing kidney function or the total intake", "Reduce the formula protein immediately because rising BUN proves excess protein delivery", "Change to a lower-calorie formula while leaving the water budget and delivery record unreviewed"]],
  ["A patient receives phenytoin through a gastric tube and concentrations fall after continuous feeding begins.", "Use a drug-specific feeding and monitoring plan", "Enteral feeding can reduce phenytoin absorption. Reconcile the formulation, delivered dose and feeding timing, assess seizure control, and monitor serum phenytoin concentration before making a dose change.", "medication-administration", ["Double the dose immediately without reviewing delivery or interactions", "Judge phenytoin exposure from the patient's INR alone", "Use warfarin's feeding-separation schedule without checking phenytoin instructions"]],
  ["A patient develops diarrhea after three sorbitol-containing liquid medications are started.", "Review sorbitol exposure and other causes, then consider suitable medication alternatives", "Sorbitol has laxative properties and can cause gastrointestinal distress. The timing warrants a medication review; it does not prove that sorbitol is the only cause or that formula must be changed.", "monitoring-complications", ["Switch immediately to a different formula without reviewing the new medications", "Assume that an oral liquid cannot contribute to diarrhea", "Dilute all medicines into the formula bag to prevent excipient effects"]],
  ["A stable ventilated adult with a usable small intestine has recurrent emesis despite head elevation and gastric motility management.", "Reassess for postpyloric access and other causes of intolerance", "Persistent intolerance and aspiration risk warrant reassessment of the cause, tube destination, and controlled delivery. Small bowel access may help selected patients but does not eliminate aspiration. More gastric volume or a destination change without assessment does not address the entire problem.", "access-route", ["Increase gastric feeding volume without reassessing the cause of emesis", "Continue the same plan because head elevation has already been attempted", "Assume postpyloric feeding would eliminate all future aspiration without other prevention measures"]],
  ["Within 48 hours of restarting enteral feeding in a malnourished adult, phosphate falls rapidly from 3.0 to 1.2 mg/dL and is difficult to correct.", "Urgently assess and treat the electrolyte abnormality and reduce calorie delivery while evaluating refeeding and other causes", "A precipitous phosphate decline after calorie reintroduction is a major refeeding warning, even with a normal baseline level. The 2020 ASPEN consensus recommends reducing calorie or dextrose delivery when electrolytes fall precipitously or are difficult to correct, together with prompt treatment and monitoring. Severe or life-threatening abnormalities may require stopping nutrition temporarily under clinical judgment; the laboratory value does not by itself exclude other causes.", "monitoring-complications", ["Continue the same calorie delivery because the initial phosphate was normal", "Increase calorie delivery to correct the low phosphate without electrolyte treatment", "Exclude refeeding because the calories were delivered through a feeding tube"]],
  ["A stable adult with a mature gastrostomy wants daytime mobility, tolerates gastric feeds, and has low aspiration risk.", "Consider bolus or cyclic delivery based on goals and tolerance", "Gastric access can support several schedules. Consider a tolerated bolus or cyclic plan that fits home goals while still meeting the prescribed volume. Trial the planned home schedule before discharge. A 24-hour connection is not always needed; home convenience does not by itself justify a jejunal destination or omission of the volume target.", "delivery-prescription", ["Keep a 24-hour pump schedule solely because every tube-fed adult must remain connected all day", "Change to jejunal access solely to obtain greater bolus flexibility", "Shorten the running hours without checking the resulting daily volume"]],
  ["A crushed extended-release antihypertensive was administered through a tube and hypotension follows.", "Urgently assess hypotension and possible dose dumping, then review the dosage form", "Crushing an extended-release product can release drug rapidly and cause toxicity. Hypotension needs prompt clinical assessment; investigate the administration error rather than assuming formula intolerance.", "medication-administration", ["Give another crushed dose because the tube may have retained the first dose", "Treat the event only by changing to a lower-calorie formula", "Restart the same crushed preparation after using a larger water flush"]],
  ["A feeding pump shows the prescribed rate, but only 55 percent of the daily target has been delivered for three days.", "Audit interruptions and redesign the safe delivery schedule", "The amount actually delivered determines nutrition received; a correct displayed rate does not prove that the scheduled volume reached the patient. Review feeding time, interruptions, and the delivery record, then choose a safe revised plan. Do not compensate automatically without considering the clinical feeding plan.", "delivery-prescription", ["Document the full daily target because the displayed hourly rate matches the order", "Increase the rate enough to replace the deficit without assessing tolerance or access", "Change the formula concentration without checking why the prescribed volume was not delivered"]],
].map(([caseText, correct, rationale, lesson, alternatives], index) => q(`09${index}`, `${caseText} What is the best next action?`, [correct, ...(alternatives || ["Continue the same plan without reassessment", "Change formula based on one isolated detail", "Ignore the access route"])], 0, rationale, lesson));

const integrationCases = [
  ["A patient in shock has escalating vasopressors, abdominal distention, and rising lactate while feeds advance.", "Hold enteral feeding and urgently evaluate perfusion and possible bowel ischemia", "Escalating vasopressor needs with abdominal distention raise concern for unsafe feeding during shock. Hold feeding and urgently assess perfusion and possible ischemia. Continuing the previous rate is not enough; neither a route change nor a formula change corrects instability. Lactate alone cannot diagnose bowel ischemia or establish enteral intolerance.", "enteral-decision", ["Stop advancement but continue the previous feeding rate while shock worsens", "Switch to jejunal feeding without reassessing perfusion", "Change to a lower-fiber formula and continue advancing during escalating shock"]],
  ["An adult ICU patient without vasopressor support has a gastric residual of 420 mL, no vomiting, pain, or distention, and stable hemodynamics. The team follows the 2016 SCCM/ASPEN adult ICU guidance.", "Assess the clinical pattern and reinforce aspiration precautions rather than automatically stopping feeding", "In this stated setting, the 2016 guideline advises against automatically holding feeding below 500 mL without other intolerance signs. Residuals from 200 to 500 mL still warrant aspiration-risk assessment and preventive measures. Do not interpret a normal examination or this value as a guarantee of safety; reassess if symptoms or hemodynamics change.", "monitoring-complications", ["Treat the value below 500 mL as proof that clinical monitoring can be stopped", "Automatically stop feeding until the residual reaches zero despite the stated clinical findings", "Use the same rule after new instability or escalating vasopressor needs without reassessment"]],
  ["A correctly positioned feeding tube is clogged after different medications were mixed together. There is no kink and no evidence of displacement.", "Use warm water gently under the declogging procedure, then review separate medication administration and flushing", "Warm water and gentle syringe movement are the initial declogging approach in the 2017 ASPEN safe-practice guidance. Review why the drugs were mixed and correct preparation and flushing practices. Acidic beverages or forceful pressure are unsuitable substitutes; if water fails, escalate through the approved protocol.", "monitoring-complications", ["Increase pressure until the mixed medications are pushed through", "Use cola as the preferred first attempt to dissolve the medication mixture", "Repeat the combined-medication method after patency returns because the daily doses are unchanged"]],
  ["A stable adult in a medical ICU has adequate digestion and absorption and no defined indication for a hydrolyzed or specialty formula. An expensive elemental formula is proposed solely because it sounds easier to absorb.", "Start with a standard polymeric formula and reassess tolerance and any specific indication", "The 2016 SCCM/ASPEN guideline recommends a standard polymeric formula initially in critically ill adults and discourages routine specialty formulas in a general medical ICU. The 2017 ASPEN safe-practice guidance supports composition, evidence, tolerance, and cost assessment. Greater hydrolysis, a diagnosis alone, and price do not establish superior outcomes.", "formula-selection", ["Choose the elemental product because greater hydrolysis guarantees better outcomes", "Select a disease-specific product solely from the admission diagnosis", "Choose the highest-cost product without reviewing its nutrient profile"]],
  ["A jejunal tube patient needs a delayed-release drug, but the available product instructions do not establish safe jejunal administration.", "Select a compatible formulation or alternative route with pharmacy input", "Delayed-release preparations should not be crushed for tube administration without verified product-specific instructions. Identify the tube destination and check the formulation and permitted administration method. If safe use of the available product at that site is not established, obtain a suitable formulation or route with pharmacy input rather than assuming compatibility.", "medication-administration", ["Crush the delayed-release preparation and give it through the jejunal tube without checking its instructions", "Use a larger water flush as a substitute for checking the dosage form and access site", "Apply nasogastric administration instructions to jejunal access without checking whether they cover that site"]],
  ["A home patient uses a 2 kcal per mL formula and receives no scheduled water beyond medication flushes.", "Calculate actual water from the formula and all other sources, then determine supplemental water against an individualized target", "The 2 kcal per mL value describes energy density, not the formula water content or the patient's water requirement. Use product water data and the amount actually delivered, count medication flushes and any other intake once, and compare the total with an individualized target. Prescribe additional water as needed rather than inferring a fixed amount from calorie density alone.", "formula-selection", ["Treat the entire formula volume as water and ignore the product water content", "Calculate supplemental water from formula water alone without counting medication flushes", "Assume that meeting the calorie target establishes adequate daily water delivery"]],
  ["A patient repeatedly coughs during feeding and the external tube marking has changed by 8 cm.", "Stop use and verify tube position before further feeding or medication", "Stop feeding and do not give fluids or medication through the tube until its intended position is confirmed. New coughing and changed external length raise concern for migration but do not identify the tip location. Reassess placement and obtain radiography if uncertain; a previous image, unchanged connector fit, or auscultation alone cannot settle the new concern.", "access-route", ["Continue feeding because the previous placement radiograph was satisfactory", "Continue feeding because an ENFit syringe still connects correctly", "Resume after air auscultation alone without resolving the placement concern"]],
  ["A patient on warfarin changes from intermittent feeding to continuous feeding and INR falls.", "Reconcile vitamin K exposure, delivery timing, adherence, and INR response", "Formula binding and vitamin K exposure can affect warfarin. Reconcile the formula and delivery change, medication timing and adherence, and follow INR rather than automatically choosing a new dose.", "medication-administration", ["Increase the dose solely because feeding is now continuous", "Eliminate all formula vitamin K without an INR monitoring plan", "Mix warfarin into the formula bag to keep delivery continuous"]],
  ["An adult receiving tube feeding develops fever and diarrhea. The feeding container has repeatedly been topped off with fresh formula instead of being replaced.", "Promptly assess the patient, discard the compromised formula and delivery system, and investigate contamination alongside other possible causes", "Topping off is unsafe because it prolongs exposure and can introduce or propagate contamination. Stop using the compromised formula and system and replace them according to safe preparation, storage, hang-time, and equipment-change instructions. Fever and diarrhea require prompt clinical assessment; the handling error raises concern but does not establish contamination as the cause or exclude medication effects, infection from another source, or other intolerance.", "monitoring-complications", ["Continue using the same container because each addition of fresh formula resets its safe hang time", "Change to a different formula composition but keep the same container and administration set", "Diagnose formula contamination from the handling error alone and defer assessment of other causes"]],
  ["A patient receives 60 mL per hour for 24 hours, but the goal is 1,800 mL daily.", "Recognize a 360 mL daily deficit and revise the safe rate or schedule", "The current prescription delivers 60 times 24, or 1,440 mL. Subtract 1,440 mL from the 1,800 mL goal to obtain a 360 mL deficit. Any revised rate or schedule must remain safe for the patient.", "delivery-prescription", ["Recognize a 600 mL deficit by treating the schedule as 20 hours", "Recognize a 240 mL deficit by using 65 mL per hour", "Conclude that 60 mL per hour for 24 hours already supplies 1,800 mL"]],
].map(([caseText, correct, rationale, lesson, alternatives], index) => q(`10${index}`, `${caseText} Which interpretation or management plan is most defensible?`, [correct, ...(alternatives || ["Use a fixed plan that ignores clinical change", "Treat the formula name as the diagnosis", "Delay all action until the next routine visit"])], 0, rationale, lesson));

const labelAndRouteCases = [
  q("110", "A hypothetical formula label states 240 kcal and 16 g protein per serving. Using 4 kcal per gram of protein, what percentage of the labeled calories comes from protein? Round to the nearest tenth of a percent.", ["26.7%", "6.7%", "60.0%", "64.0%"], 0, "Protein supplies 16 times 4, or 64 kcal. Divide 64 by the stated 240 kcal and multiply by 100: 26.666...%, or 26.7%. The denominator is labeled energy, not grams of protein.", "formula-selection"),
  q("111", "A hypothetical formula serving contains 9 g fat. Using 9 kcal per gram of fat, how much energy comes from fat in that serving?", ["81 kcal", "36 kcal", "30.6 kcal", "9 kcal"], 0, "Multiply 9 g fat by 9 kcal per gram to obtain 81 kcal. The 4 kcal per gram factor applies to protein and enteral carbohydrate; 3.4 kcal per gram is used for parenteral dextrose.", "formula-selection"),
  q("112", "A hypothetical formula contains 23 g carbohydrate per full serving. If half a serving is delivered, how much carbohydrate energy is received using 4 kcal per gram?", ["46 kcal", "92 kcal", "11.5 kcal", "39.1 kcal"], 0, "A full serving supplies 23 times 4, or 92 kcal from carbohydrate. Half a serving provides 46 kcal. First identify the nutrient energy, then scale it to the delivered fraction.", "formula-selection"),
  q("113", "A hypothetical formula label states 240 kcal per 240 mL serving. Of one serving, 60 mL is spilled and the remaining 180 mL is accurately delivered. How much labeled energy is received?", ["180 kcal", "240 kcal", "60 kcal", "320 kcal"], 0, "The delivered fraction is 180 divided by 240, or 0.75. Multiply 240 kcal by 0.75 to obtain 180 kcal. The spilled portion is excluded from intake.", "formula-selection"),
  q("114", "A hypothetical label declares 240 kcal per serving with 16 g protein, 23 g carbohydrate, and 9 g fat. The simple 4/4/9 calculation totals 237 kcal. Which denominator should be used to calculate the percentage of the declared calories supplied by protein?", ["240 kcal, the declared serving energy", "237 kcal, replacing the declared total with the calculated sum", "64 kcal, the protein energy alone", "48 g, the sum of macronutrient masses"], 0, "The question asks about declared calories, so use the stated 240 kcal total. Protein energy is 16 times 4, or 64 kcal. Do not silently replace the label denominator because the simple nutrient-factor sum differs.", "formula-selection"),
  q("115", "Which description correctly distinguishes PEG from PEJ access?", ["PEG reaches the stomach; PEJ reaches the jejunum", "Both end in the stomach and differ only in insertion technique", "PEG reaches the jejunum; PEJ reaches the stomach", "PEG reaches the stomach; PEJ ends in the duodenum"], 0, "PEG means percutaneous endoscopic gastrostomy and ends in the stomach. PEJ means percutaneous endoscopic jejunostomy and ends in the jejunum. Nasogastric access passes through the nose to the stomach.", "access-route"),
  q("116", "An oil-based ciprofloxacin oral suspension is being considered for a feeding tube. Which formulation decision addresses the problem described for this suspension?", ["Check a suitable immediate-release tablet and its product-specific tube instructions", "Use the suspension because every oral liquid is tube compatible", "Mix the suspension into the formula so adhesion cannot occur", "Crush an extended-release tablet instead without checking its instructions"], 0, "The oil-based oral suspension can adhere to the feeding tube. The immediate-release tablet is the alternative described for crushing and mixing with water, with flushing before and after. Verify the exact product and tube instructions; the separate cation-related absorption interaction still requires review.", "medication-administration"),
  q("117", "A prescribed warfarin administration plan holds tube feeding for one hour before and one hour after an 08:00 dose. Which feeding window follows that plan?", ["Stop at 07:00 and restart at 09:00", "Stop at 07:00 and restart immediately at 08:00", "Stop at 08:00 and restart at 09:00", "Stop at 06:00 and restart at 10:00"], 0, "One hour before 08:00 is 07:00, and one hour after is 09:00. This implements the stated warfarin plan, not a universal hold for all medications.", "medication-administration"),
];

export const enteralNutritionQuestionBank = [
  ...core,
  ...rateCases,
  ...deliveredVolumeCases,
  ...waterCases,
  ...diagnosticCases,
  ...integrationCases,
  ...labelAndRouteCases,
];

if (enteralNutritionQuestionBank.length !== 108) {
  throw new Error(`Enteral nutrition question bank must contain 108 questions, found ${enteralNutritionQuestionBank.length}.`);
}
